import numpy as np
import time


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, h)


def coord_sweep(h, deadline, rng=None):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in (0.0, 0.5, 0.8, 0.9, 1.1, 1.25, 1.6, 2.0):
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        for add in (-0.5, -0.2, 0.2, 0.5):
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def coord_descent(h, deadline, sweeps=3, rng=None):
    h = np.asarray(h, dtype=float).copy()
    best_r = R_of(h)
    for _ in range(sweeps):
        if time.process_time() >= deadline:
            break
        h, r = coord_sweep(h, deadline, rng)
        if r > best_r:
            best_r = r
    return h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(2024)

