    best_r_global = -1.0

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        r = R_of(base)
        print("start R =", r, "N =", len(base))
        best_global = base.copy()
        best_r_global = r

    # Try a few different starting N values in parallel-ish, then refine.
    # Key change: also resume from start's N and try multiple N scales.
    current = None
    current_r = -1.0
    if best_global is not None:
        current = best_global.copy()
        current_r = best_r_global

    levels = [16, 24, 32, 48, 64]
    for li, N in enumerate(levels):
        now = time.process_time()
        if now >= deadline:
            break
        remaining_levels = len(levels) - li
        level_deadline = now + (deadline - now) / remaining_levels * 0.9
        best_h = None
        best_r = -1.0
        seeds = []
        if current is not None:
            seeds.append(resample(current, N))
        n_restarts = 200
        for k in range(n_restarts):
            if time.process_time() >= level_deadline:
                break
            if k < len(seeds):
                h0 = seeds[k].copy()
            else:
                h0 = rng.random(N) * 1.0
            h0 = np.maximum(0.0, h0 * (1.0 + 0.1 * rng.standard_normal(N)))
            h, r = coord_descent(h0, level_deadline, sweeps=3, rng=rng)
            if r > best_r:
                best_r = r
                best_h = h.copy()
        if best_h is None:
            if current is not None:
                best_h = resample(current, N)
                best_r = R_of(best_h)
            else:
                best_h = np.ones(N)
                best_r = R_of(best_h)
        if time.process_time() < level_deadline:
            best_h, best_r = coord_descent(best_h, level_deadline, sweeps=10, rng=rng)
        current = best_h
        current_r = best_r
        print(f"level N={N} best R={best_r:.6f}")
        if best_r > best_r_global:
            best_r_global = best_r
            best_global = best_h.copy()

    # Fine levels — try several N values including start's N
    fine_Ns = [100, 150, 200, 300, 400]
    if best_global is not None and len(best_global) not in fine_Ns:
        fine_Ns.append(len(best_global))
    for N in fine_Ns:
        if time.process_time() >= deadline:
            break
        if current is not None:
            seed = resample(current, N)
        elif best_global is not None:
            seed = resample(best_global, N)
        else:
            seed = np.ones(N)
        h, r = coord_descent(seed, deadline, sweeps=10, rng=rng)
        print(f"fine N={N} R={r:.6f}")
        if r > best_r_global:
            best_r_global = r
            best_global = h.copy()
        current = h

    # Polish at best N and neighbours
    while time.process_time() < deadline and best_global is not None:
        h, r = coord_descent(best_global, deadline, sweeps=3, rng=rng)
        if r > best_r_global:
            best_r_global = r
            best_global = h.copy()
        else:
            break

    if best_global is None:
        best_global = np.ones(16)
        best_r_global = R_of(best_global)

    print("final R =", best_r_global, "N =", len(best_global))
    return best_global

import numpy as np
import time


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def R_fft(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    n = 2 * len(h) - 1
    c = np.fft.irfft(np.fft.rfft(h, n=n) ** 2, n=n)
    L = np.concatenate(([0.0], c, [0.0]))
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, h)


def grad_R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    N = len(h)
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C)
    return dR_dh


def grad_R_fft(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    n = 2 * N - 1
    c = np.fft.irfft(np.fft.rfft(h, n=n) ** 2, n=n)
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    # correlate(dA_dc, h, 'valid') via FFT: irfft(rfft(dA_dc) * rfft(h[::-1]))
    nf = len(dA_dc) + N - 1
    conv = np.fft.irfft(np.fft.rfft(dA_dc, n=nf) * np.fft.rfft(h[::-1], n=nf), n=nf)
    # valid correlation length N: conv[N-1 : 2N-1]
    dA_dh = 2.0 * conv[N-1:2*N-1]
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C)
    return dR_dh


def refine_grad(h, deadline, rng=None, tries=30, Rfun=R_of, Gfun=grad_R):
    h = np.asarray(h, dtype=float).copy()
    cur_r = Rfun(h)
    scale = h.max() if h.max() > 0 else 1.0
    lr = 0.1 * scale / max(1.0, np.linalg.norm(h) + 1e-9)
    for t in range(tries):
        if time.process_time() >= deadline:
            break
        g = Gfun(h)
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr * g / gn
        improved = False
        for alpha in (1.0, 0.5, 0.25, 0.1):
            cand = np.maximum(0.0, h + alpha * step)
            r = Rfun(cand)
            if r > cur_r:
                h = cand
                cur_r = r
                improved = True
                lr *= 1.2
                break
        if not improved:
            lr *= 0.5
            if lr < 1e-10 * scale:
                break
    return h, cur_r


def coord_sweep(h, deadline, rng=None, Rfun=R_of):
    h = np.asarray(h, dtype=float).copy()
    cur_r = Rfun(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in (0.0, 0.5, 0.8, 0.9, 1.1, 1.25, 1.6, 2.0):
            h[i] = orig * mult
            r = Rfun(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        for add in (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5):
            h[i] = max(0.0, orig + add * scale)
            r = Rfun(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def coord_descent(h, deadline, sweeps=3, rng=None, Rfun=R_of):
    h = np.asarray(h, dtype=float).copy()
    best_r = Rfun(h)
    for _ in range(sweeps):
        if time.process_time() >= deadline:
            break
        h, r = coord_sweep(h, deadline, rng, Rfun=Rfun)
        if r > best_r:
            best_r = r
    return h, best_r


def polish_lbfgs(h, deadline, Rfun=R_of, Gfun=grad_R):
    try:
        from scipy.optimize import minimize
    except Exception:
        return h, Rfun(h)
    h = np.asarray(h, dtype=float).copy()
    scale = h.max() if h.max() > 0 else 1.0
    x0 = h / scale

    def fun(x):
        if time.process_time() >= deadline:
            raise TimeoutError
        return -Rfun(np.maximum(0.0, x))

    def jac(x):
        if time.process_time() >= deadline:
            raise TimeoutError
        return -Gfun(np.maximum(0.0, x))

    try:
        res = minimize(fun, x0, jac=jac, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': 200, 'ftol': 1e-15, 'gtol': 1e-12})
        cand = np.maximum(0.0, res.x)
        r = Rfun(cand)
        if r > Rfun(h):
            return cand, r
    except Exception:
        pass
    return h, Rfun(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82
    rng = np.random.default_rng(777)

    best_global = None
    best_r_global = -1.0

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        r = R_of(base)
        print("start R =", r, "N =", len(base))
        best_global = base.copy()
        best_r_global = r

    levels = [400, 800, 1600, 3200]
    current = None

    # Seed N=400 from start
    if best_global is not None:
        current = resample(best_global, 400)
    else:
        current = np.ones(400)

    for li, N in enumerate(levels):
        now = time.process_time()
        if now >= deadline:
            break
        remaining_levels = len(levels) - li
        level_deadline = now + (deadline - now) / remaining_levels * 0.92

        seed = resample(current, N)
        best_h = seed.copy()
        best_r = R_fft(best_h)

        # Gradient ascent
        h, r = refine_grad(seed, level_deadline, rng, tries=40, Rfun=R_fft, Gfun=grad_R_fft)
        if r > best_r:
            best_h, best_r = h, r

        # Coord descent
        h, r = coord_descent(best_h, level_deadline, sweeps=4, rng=rng, Rfun=R_fft)
        if r > best_r:
            best_h, best_r = h, r

        # L-BFGS polish
        h, r = polish_lbfgs(best_h, level_deadline, Rfun=R_fft, Gfun=grad_R_fft)
        if r > best_r:
            best_h, best_r = h, r

        # Extra grad/coord polish
        if time.process_time() < level_deadline:
            h, r = refine_grad(best_h, level_deadline, rng, tries=30, Rfun=R_fft, Gfun=grad_R_fft)
            if r > best_r:
                best_h, best_r = h, r
            h, r = coord_descent(best_h, level_deadline, sweeps=6, rng=rng, Rfun=R_fft)
            if r > best_r:
                best_h, best_r = h, r

        current = best_h
        print(f"level N={N} best R={best_r:.6f}")

        if best_r > best_r_global:
            best_r_global = best_r
            best_global = best_h.copy()

    # Final polish at best N
    while time.process_time() < deadline and best_global is not None:
        h, r = polish_lbfgs(best_global, deadline, Rfun=R_fft, Gfun=grad_R_fft)
        if r > best_r_global:
            best_r_global = r
            best_global = h.copy()
        else:
            break

    if best_global is None:
        best_global = np.ones(16)
        best_r_global = R_of(best_global)

    print("final R =", best_r_global, "N =", len(best_global))
    return best_global

import numpy as np
import time


def _knots(h):
    return np.concatenate(([0.0], np.convolve(h, h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def R_fft(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    n = 2 * len(h) - 1
    c = np.fft.irfft(np.fft.rfft(h, n=n) ** 2, n=n)
    L = np.concatenate(([0.0], c, [0.0]))
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, h)


def grad_R_fft(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    N = len(h)
    n = 2 * N - 1
    c = np.fft.irfft(np.fft.rfft(h, n=n) ** 2, n=n)
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    nf = len(dA_dc) + N - 1
    conv = np.fft.irfft(np.fft.rfft(dA_dc, n=nf) * np.fft.rfft(h[::-1], n=nf), n=nf)
    dA_dh = 2.0 * conv[N-1:2*N-1]
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    dC_dh = np.zeros(N)
    jmax = int(np.argmax(c))
    dC_dh[jmax - (N-1) if jmax >= N-1 else 0] = 0.0  # placeholder; handled below
    # derivative of max: d c_j / d h_i = 2 h_{j-i}
    # jmax is index in c (0..2N-2); c[jmax] = sum_i h_i h_{jmax-i}
    dC_dh = np.zeros(N)
    for i in range(N):
        k = jmax - i
        if 0 <= k < N:
            dC_dh[i] = 2.0 * h[k]
    dR_dh = (dA_dh * B - A * dB_dh) * C - (A * B) * dC_dh
    dR_dh /= (B * B * C * C)
    return dR_dh


def polish_lbfgs(h, deadline, Rfun=R_fft, Gfun=grad_R_fft):
    try:
        from scipy.optimize import minimize
    except Exception:
        return h, Rfun(h)
    h = np.asarray(h, dtype=float).copy()
    scale = h.max() if h.max() > 0 else 1.0
    x0 = h / scale

    def fun(x):
        if time.process_time() >= deadline:
            raise TimeoutError
        return -Rfun(np.maximum(0.0, x))

    def jac(x):
        if time.process_time() >= deadline:
            raise TimeoutError
        return -Gfun(np.maximum(0.0, x))

    try:
        res = minimize(fun, x0, jac=jac, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(x0),
                       options={'maxiter': 400, 'ftol': 1e-16, 'gtol': 1e-13})
        cand = np.maximum(0.0, res.x)
        r = Rfun(cand)
        if r > Rfun(h):
            return cand, r
    except Exception:
        pass
    return h, Rfun(h)


def coord_sweep(h, deadline, rng=None, Rfun=R_fft):
    h = np.asarray(h, dtype=float).copy()
    cur_r = Rfun(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        cands = [orig * m for m in (0.0, 0.5, 0.8, 0.9, 0.97, 1.03, 1.1, 1.25, 1.6, 2.0)]
        cands += [max(0.0, orig + a * scale) for a in (-0.3, -0.1, -0.03, 0.03, 0.1, 0.3)]
        for val in cands:
            if val == orig:
                continue
            h[i] = val
            r = Rfun(h)
            if r > best_r:
                best_r = r
                best_val = val
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(9001)

    best_global = None
    best_r_global = -1.0

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        r = R_of(base)
        print("start R =", r, "N =", len(base))
        best_global = base.copy()
        best_r_global = r
        current = base.copy()
    else:
        current = np.ones(200)

    # Try multiple resolutions; the optimum seems to live at moderate N.
    base_N = len(current)
    levels = [base_N]
    for mult in (0.5, 2.0, 0.25, 4.0, 0.125, 8.0):
        N = int(round(base_N * mult))
        if 32 <= N <= 50000 and N not in levels:
            levels.append(N)
    # Move small levels first to seed larger ones.
    levels = sorted(set(levels))

    for li, N in enumerate(levels):
        now = time.process_time()
        if now >= deadline:
            break
        remaining = len(levels) - li
        level_deadline = now + (deadline - now) / remaining * 0.95

        seed = resample(current, N)
        seed = np.maximum(0.0, seed)
        if seed.sum() <= 0:
            seed = np.ones(N)
        h = seed
        r = R_fft(h)

        # Alternate L-BFGS and coordinate sweeps.
        for it in range(6):
            if time.process_time() >= level_deadline:
                break
            h2, r2 = polish_lbfgs(h, level_deadline)
            if r2 > r:
                h, r = h2, r2
            if time.process_time() >= level_deadline:
                break
            h2, r2 = coord_sweep(h, level_deadline, rng)
            if r2 > r:
                h, r = h2, r2
            else:
                break

        print(f"level N={N} R={r:.6f}")
        if r > best_r_global:
            best_r_global = r
            best_global = h.copy()
            current = h.copy()

    # Final polish at best N
    if best_global is not None:
        while time.process_time() < deadline:
            h, r = polish_lbfgs(best_global, deadline)
            if r > best_r_global + 1e-12:
                best_r_global = r
                best_global = h.copy()
            else:
                break
        if time.process_time() < deadline:
            h, r = coord_sweep(best_global, deadline, rng)
