import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, h)


def grad_R(h):
    """Gradient of R wrt h with a subgradient for the max (C) term."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    active = np.where(L > C * (1.0 - 1e-9))[0]
    dC_dh = np.zeros_like(h)
    N = len(h)
    for kL in active:
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * h[k - idx]
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


# ---- symmetric parametrization helpers ----

def build_h(u, N):
    """Build symmetric h of length N from u of length m=ceil(N/2)."""
    u = np.asarray(u, dtype=float)
    m = len(u)
    if N % 2 == 0:
        # m = N/2, h = concat(u, u[::-1])
        return np.concatenate((u, u[::-1]))
    else:
        # m = (N+1)/2, h = concat(u, u[-2::-1])
        return np.concatenate((u, u[-2::-1]))


def fold_grad(g, N):
    """Fold gradient wrt h into gradient wrt u (length m=ceil(N/2))."""
    m = (N + 1) // 2
    gu = g[:m].copy()
    # positions N-1, N-2, ... map to u indices 0, 1, ...
    # for even N: h = [u0..u_{m-1}, u_{m-1}..u_0]; mirror index j -> N-1-j = u index
    # for odd N: h = [u0..u_{m-1}, u_{m-2}..u_0]
    # In both cases, h[N-1-j] = u[j] for j=0..m-1 (check: even N, j=m-1 -> h[m]=u[m-1] yes;
    # odd N, j=m-1 -> h[m-1]=u[m-1] center, j=m-2 -> h[m]=u[m-2] yes).
    # So gu[j] = g[j] + g[N-1-j] for j where N-1-j != j, else just g[j].
    for j in range(m):
        k = N - 1 - j
        if k != j:
            gu[j] += g[k]
    return gu


def R_of_u(u, N):
    return R_of(build_h(u, N))


def grad_R_u(u, N):
    h = build_h(u, N)
    g = grad_R(h)
    return fold_grad(g, N)


def polish_lbfgs_u(u, N, deadline, maxiter=3000):
    u = np.asarray(u, dtype=float).copy()
    if time.process_time() >= deadline:
        return u, R_of_u(u, N)
    try:
        res = minimize(
            fun=lambda x: -R_of_u(x, N),
            jac=lambda x: -grad_R_u(x, N),
            x0=u,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(u),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        cand = np.maximum(0.0, res.x)
        r = R_of_u(cand, N)
        if r > R_of_u(u, N):
            return cand, r
    except Exception:
        pass
    return u, R_of_u(u, N)


def refine_grad_u(u, N, deadline, rng=None, tries=30):
    u = np.asarray(u, dtype=float).copy()
    cur_r = R_of_u(u, N)
    scale = u.max() if u.max() > 0 else 1.0
    lr = 0.1 * scale / max(1.0, np.linalg.norm(u) + 1e-9)
    for t in range(tries):
        if time.process_time() >= deadline:
            break
        g = grad_R_u(u, N)
        gn = np.linalg.norm(g)
        if gn < 1e-12:
            break
        step = lr * g / gn
        improved = False
        for alpha in (1.0, 0.5, 0.25, 0.1):
            cand = np.maximum(0.0, u + alpha * step)
            r = R_of_u(cand, N)
            if r > cur_r:
                u = cand
                cur_r = r
                improved = True
                lr *= 1.2
                break
        if not improved:
            lr *= 0.5
            if lr < 1e-10 * scale:
                break
    return u, cur_r


def coord_sweep_u(u, N, deadline, rng=None):
    u = np.asarray(u, dtype=float).copy()
    cur_r = R_of_u(u, N)
    m = len(u)
    scale = u.max() if u.max() > 0 else 1.0
    order = np.arange(m)
    if rng is not None:
        rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = u[i]
        best_val = orig
        best_r = cur_r
        for mult in (0.0, 0.5, 0.8, 0.9, 1.1, 1.25, 1.6, 2.0):
            u[i] = orig * mult
            r = R_of_u(u, N)
            if r > best_r:
                best_r = r
                best_val = u[i]
        for add in (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5):
            u[i] = max(0.0, orig + add * scale)
            r = R_of_u(u, N)
            if r > best_r:
                best_r = r
                best_val = u[i]
        u[i] = best_val
        cur_r = best_r
    return u, cur_r


def coord_descent_u(u, N, deadline, sweeps=3, rng=None):
    u = np.asarray(u, dtype=float).copy()
    best_r = R_of_u(u, N)
    for _ in range(sweeps):
        if time.process_time() >= deadline:
            break
        u, r = coord_sweep_u(u, N, deadline, rng)
        if r > best_r:
            best_r = r
    return u, best_r


def symmetrize(h):
    return (h + h[::-1]) / 2.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82
    rng = np.random.default_rng(777)

    best_global = None
    best_r_global = -1.0

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        r = R_of(base)
        print("start R =", r, "N =", len(base))
        best_global = base.copy()
        best_r_global = r

    # symmetric seed from symmetrized start
    sym_seed = None
    if best_global is not None:
        sym_seed = symmetrize(best_global)
        rs = R_of(sym_seed)
        print("symmetrized start R =", rs, "N =", len(sym_seed))
        if rs > best_r_global:
            best_r_global = rs
            best_global = sym_seed.copy()

    levels = [200, 300, 400]

    for li, N in enumerate(levels):
        now = time.process_time()
        if now >= deadline:
            break
        remaining = len(levels) - li
        level_deadline = now + (deadline - now) / remaining * 0.92
        m = (N + 1) // 2

        best_u = None
        best_r = -1.0
        seeds = []
        if best_global is not None:
            seeds.append(resample(symmetrize(best_global), N)[:m].copy())
        if sym_seed is not None:
            seeds.append(resample(sym_seed, N)[:m].copy())

        for s in seeds:
            if time.process_time() >= level_deadline:
                break
            u, r = refine_grad_u(s, N, level_deadline, rng, tries=40)
            u, r = coord_descent_u(u, N, level_deadline, sweeps=4, rng=rng)
            if r > best_r:
                best_r = r
                best_u = u.copy()

        n_restarts = 40
        for k in range(n_restarts):
            if time.process_time() >= level_deadline:
                break
            if seeds and k % 3 == 0:
                u0 = seeds[k % len(seeds)] * (1.0 + 0.1 * rng.standard_normal(m))
            else:
                u0 = rng.random(m)
            u0 = np.maximum(0.0, u0)
            u, r = refine_grad_u(u0, N, level_deadline, rng, tries=20)
            u, r = coord_descent_u(u, N, level_deadline, sweeps=2, rng=rng)
            if r > best_r:
                best_r = r
                best_u = u.copy()

        if best_u is None:
            best_u = seeds[0] if seeds else np.ones(m)
            best_r = R_of_u(best_u, N)

        if time.process_time() < level_deadline:
            best_u, best_r = polish_lbfgs_u(best_u, N, level_deadline)
            best_u, best_r = coord_descent_u(best_u, N, level_deadline, sweeps=8, rng=rng)

        h = build_h(best_u, N)
        r_true = R_of(h)
        print(f"sym level N={N} R={r_true:.6f}")

        if r_true > best_r_global:
            best_r_global = r_true
            best_global = h.copy()

    # final polish: L-BFGS in u-space on best N, then coord
    if best_global is not None and time.process_time() < deadline:
        N = len(best_global)
        m = (N + 1) // 2
        u = symmetrize(best_global)[:m].copy()
        u, r = polish_lbfgs_u(u, N, deadline)
        u, r = coord_descent_u(u, N, deadline, sweeps=2, rng=rng)
        h = build_h(u, N)
        r_true = R_of(h)
        print(f"final sym polish R={r_true:.6f} N={N}")
        if r_true > best_r_global:
            best_r_global = r_true
            best_global = h.copy()

    if best_global is None:
        best_global = np.ones(16)
        best_r_global = R_of(best_global)

    print("final R =", best_r_global, "N =", len(best_global))
    return best_global

