import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, h)


def grad_R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    active = np.where(L > C * (1.0 - 1e-9))[0]
    dC_dh = np.zeros_like(h)
    N = len(h)
    for kL in active:
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * h[k - idx]
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs(h, deadline, maxiter=3000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h, R_of(h)
    try:
        res = minimize(
            fun=lambda x: -R_of(x),
            jac=lambda x: -grad_R(x),
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        cand = np.maximum(0.0, res.x)
        r = R_of(cand)
        if r > R_of(h):
            return cand, r
    except Exception:
        pass
    return h, R_of(h)


def coord_sweep(h, deadline, rng=None, fine=False):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    mults = (0.0, 0.5, 0.8, 0.9, 0.95, 1.05, 1.1, 1.25, 1.6, 2.0)
    if fine:
        mults = (0.0, 0.9, 0.95, 0.98, 1.02, 1.05, 1.1, 1.25)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in mults:
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        adds = (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5)
        if fine:
            adds = (-0.05, -0.01, 0.01, 0.05)
        for add in adds:
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def coord_descent(h, deadline, sweeps=3, rng=None, fine=False):
    h = np.asarray(h, dtype=float).copy()
    best_r = R_of(h)
    for _ in range(sweeps):
        if time.process_time() >= deadline:
            break
        h, r = coord_sweep(h, deadline, rng, fine=fine)
        if r > best_r:
            best_r = r
    return h, best_r


def smooth_perturb(h, rng, eps=None):
    N = len(h)
    x = np.linspace(0.0, 1.0, N)
    if eps is None:
        eps = rng.uniform(0.005, 0.04)
    p = np.ones(N)
    for _ in range(3):
        f = rng.uniform(0.5, 8.0)
        a = rng.standard_normal()
        phi = rng.uniform(0.0, 2.0 * np.pi)
        p += eps * a * np.cos(np.pi * f * x + phi)
    p = np.clip(p, 0.6, 1.4)
    return np.maximum(0.0, h * p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(20240607)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # Initial polish of the start
    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng)
        if r > best_r:
            best, best_r = h, r
        print(f"initial polish R={best_r:.6f} N={len(best)}")

    it = 0
    while time.process_time() < deadline:
        it += 1
        # Try small resamples to nearby N to escape
        if it % 4 == 0:
            N_new = int(np.clip(len(best) + rng.integers(-20, 21), 200, 320))
            cand = resample(best, N_new)
        else:
            cand = smooth_perturb(best, rng)

        # local polish
        h, r = polish_lbfgs(cand, deadline)
        if time.process_time() >= deadline:
            if r > best_r:
                best, best_r = h, r
            break
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng)

        if r > best_r + 1e-10:
            best, best_r = h, r
            print(f"hop {it}: accepted R={best_r:.6f} N={len(best)}")

    # Final fine polish
    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng, fine=True)
        if r > best_r:
            best, best_r = h, r
        print(f"final polish R={best_r:.6f} N={len(best)}")

