    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    N = len(h)
    # dC/dh: derivative of max. c[j] = sum_i h_i h_{j-i}.
    # Use all near-max knots (plateau) for a better subgradient.
    active = np.where(L >= C * (1.0 - 1e-7))[0]
    dC_dh = np.zeros(N)
    w = 1.0 / len(active)
    for kL in active:
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * h[k - idx] * w
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs(h, deadline, maxiter=4000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h, R_of(h)
    h0_r = R_of(h)

    def fun(x):
        if time.process_time() >= deadline:
            raise TimeoutError
        return -R_of(np.maximum(0.0, x))

    def jac(x):
        if time.process_time() >= deadline:
            raise TimeoutError
        return -grad_R(np.maximum(0.0, x))

    try:
        res = minimize(fun, h, jac=jac, method='L-BFGS-B',
                       bounds=[(0.0, None)] * len(h),
                       options={'maxiter': maxiter, 'ftol': 1e-17,
                                'gtol': 1e-14, 'maxls': 80})
        cand = np.maximum(0.0, res.x)
        r = R_of(cand)
        if r > h0_r:
