        for add in (-0.3, -0.1, -0.03, 0.03, 0.1, 0.3):
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def coord_descent(h, deadline, sweeps=3, rng=None):
    h = np.asarray(h, dtype=float).copy()
    best_r = R_of(h)
    for _ in range(sweeps):
        if time.process_time() >= deadline:
            break
        h, r = coord_sweep(h, deadline, rng)
        if r > best_r:
            best_r = r
        else:
            break
    return h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82
    rng = np.random.default_rng(20240608)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    def try_path(h_init, N_mid, N_final, label):
        nonlocal best, best_r
        if time.process_time() >= deadline:
            return
        h = resample(h_init, N_mid)
        h, r = polish_lbfgs(h, deadline)
        if time.process_time() >= deadline:
            h2 = resample(h, N_final)
            r2 = R_of(h2)
            if r2 > best_r:
                best, best_r = h2, r2
                print(f"{label}: accepted R={best_r:.6f} N={len(best)}")
            return
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng)
        h2 = resample(h, N_final)
