    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in (0.0, 0.5, 0.75, 0.9, 0.97, 1.03, 1.1, 1.33, 1.6, 2.0):
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
