    return h, best_r


def smooth_perturb(h, rng, eps=None):
    N = len(h)
    x = np.linspace(0.0, 1.0, N)
    if eps is None:
        eps = rng.uniform(0.005, 0.04)
    p = np.ones(N)
    for _ in range(3):
        f = rng.uniform(0.5, 6.0)
        a = rng.standard_normal()
        phi = rng.uniform(0.0, 2.0 * np.pi)
        p += eps * a * np.cos(np.pi * f * x + phi)
    p = np.clip(p, 0.7, 1.3)
    return np.maximum(0.0, h * p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80
    rng = np.random.default_rng(987654321)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # initial strong polish from start
    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng)
        if r > best_r:
            best, best_r = h, r
        print(f"initial polish R={best_r:.6f} N={len(best)}")

    # multi-N climbing
    N0 = len(best)
    N_list = [N0, N0, N0, max(64, N0 - 8), N0 + 8, N0, N0 + 16, max(64, N0 - 16)]
    N_idx = 0
    it = 0
    while time.process_time() < deadline:
        it += 1
        N_new = N_list[N_idx % len(N_list)]
        N_idx += 1

        if N_new != len(best):
            cand = resample(best, N_new)
            cand = np.maximum(0.0, cand * (1.0 + 0.015 * rng.standard_normal(len(cand))))
        else:
            cand = smooth_perturb(best, rng)

        h, r = polish_lbfgs(cand, deadline)
        if time.process_time() >= deadline:
            if r > best_r:
                best, best_r = h, r
            break
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng)

        if r > best_r + 1e-10:
            best, best_r = h, r
            print(f"hop {it}: accepted R={best_r:.6f} N={len(best)}")

    # final polish at current N only (don't change N at end)
    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        if r > best_r:
            best, best_r = h, r
        h, r = coord_descent(best, deadline, sweeps=2, rng=rng)
        if r > best_r:
            best, best_r = h, r

    print("final R =", best_r, "N =", len(best))
    return np.asarray(best, dtype=float)

