    x = np.linspace(0.0, 1.0, N)
    if eps is None:
        eps = rng.uniform(0.005, 0.04)
    p = np.ones(N)
    for _ in range(3):
        f = rng.uniform(0.5, 8.0)
        a = rng.standard_normal()
        phi = rng.uniform(0.0, 2.0 * np.pi)
        p += eps * a * np.cos(np.pi * f * x + phi)
    p = np.clip(p, 0.6, 1.4)
    return np.maximum(0.0, h * p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(77700123)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # Initial polish of the start
    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng, fine=True)
        if r > best_r:
            best, best_r = h, r
        print(f"initial polish R={best_r:.6f} N={len(best)}")

    # Main basin-hopping loop with varied moves and N resampling
    it = 0
    stall = 0
    while time.process_time() < deadline:
        it += 1
        move = it % 6
        if move == 0:
            N_new = int(np.clip(len(best) + rng.integers(-40, 41), 180, 340))
            cand = resample(best, N_new)
        elif move == 1:
            # scale-based perturbation on random subset
            cand = best.copy()
            N = len(cand)
            idx = rng.choice(N, size=max(1, N // 6), replace=False)
            cand[idx] = np.maximum(0.0, cand[idx] * np.exp(rng.normal(0, 0.15, size=idx.size)))
        elif move == 2:
            cand = smooth_perturb(best, rng, eps=rng.uniform(0.01, 0.06))
        elif move == 3:
            cand = resample(best, int(np.clip(len(best) + rng.integers(-10, 11), 180, 340)))
        else:
            cand = smooth_perturb(best, rng)

        h, r = polish_lbfgs(cand, deadline)
        if time.process_time() >= deadline:
            if r > best_r:
                best, best_r = h, r
            break
        h, r = coord_descent(h, deadline, sweeps=1, rng=rng, fine=True)

        if r > best_r + 1e-9:
            best, best_r = h, r
            stall = 0
            print(f"hop {it}: accepted R={best_r:.6f} N={len(best)}")
        else:
            stall += 1
            # occasional restart from best via stronger perturbation
            if stall >= 8 and time.process_time() < deadline:
                cand = smooth_perturb(best, rng, eps=rng.uniform(0.05, 0.12))
                h, r = polish_lbfgs(cand, deadline)
                if r > best_r:
                    best, best_r = h, r
                    print(f"restart {it}: R={best_r:.6f} N={len(best)}")
                stall = 0

    # Final polish
    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        h, r = coord_descent(h, deadline, sweeps=2, rng=rng, fine=True)
        if r > best_r:
            best, best_r = h, r
        print(f"final polish R={best_r:.6f} N={len(best)}")

    print("final R =", best_r, "N =", len(best))
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    return np.concatenate(([0.0], c, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    sq = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    inf = L.max()
    if inf <= 0:
        return -1.0
    return sq / (s * s * inf)


def resample(h, N):
    h = np.asarray(h, dtype=float)
    M = len(h)
    if M == N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, M)
    x_new = np.linspace(0.0, 1.0, N)
    return np.interp(x_new, x_old, h)


def grad_R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    L = _knots(h)
    dA_dL = (2.0 * L + np.concatenate(([0.0], L[:-1])) + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:len(L)-1]
    dA_dh = 2.0 * np.correlate(dA_dc, h, mode='valid')
    dB_dh = 2.0 * s
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    B = s * s
    C = L.max()
    active = np.where(L > C * (1.0 - 1e-9))[0]
    dC_dh = np.zeros_like(h)
    N = len(h)
    for kL in active:
        k = kL - 1
        if k < 0 or k > 2 * N - 2:
            continue
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        if lo <= hi:
            idx = np.arange(lo, hi + 1)
            dC_dh[idx] += 2.0 * h[k - idx]
    dR_dh = (dA_dh * B - A * dB_dh) / (B * B * C) - A * dC_dh / (B * C * C)
    return dR_dh


def polish_lbfgs(h, deadline, maxiter=3000):
    h = np.asarray(h, dtype=float).copy()
    if time.process_time() >= deadline:
        return h, R_of(h)
    try:
        res = minimize(
            fun=lambda x: -R_of(x),
            jac=lambda x: -grad_R(x),
            x0=h,
            method='L-BFGS-B',
            bounds=[(0.0, None)] * len(h),
            options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13, 'maxls': 60},
        )
        cand = np.maximum(0.0, res.x)
        r = R_of(cand)
        if r > R_of(h):
            return cand, r
    except Exception:
        pass
    return h, R_of(h)


def coord_sweep(h, deadline, rng=None):
    h = np.asarray(h, dtype=float).copy()
    cur_r = R_of(h)
    N = len(h)
    scale = h.max() if h.max() > 0 else 1.0
    order = np.arange(N)
    if rng is not None:
        rng.shuffle(order)
    for i in order:
        if time.process_time() >= deadline:
            break
        orig = h[i]
        best_val = orig
        best_r = cur_r
        for mult in (0.0, 0.5, 0.8, 0.9, 1.1, 1.25, 1.6, 2.0):
            h[i] = orig * mult
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        for add in (-0.5, -0.2, -0.05, 0.05, 0.2, 0.5):
            h[i] = max(0.0, orig + add * scale)
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_val = h[i]
        h[i] = best_val
        cur_r = best_r
    return h, cur_r


def smooth_perturb(h, rng, eps=None):
    N = len(h)
    x = np.linspace(0.0, 1.0, N)
    if eps is None:
        eps = rng.uniform(0.01, 0.08)
    p = np.ones(N)
    for _ in range(3):
        f = rng.uniform(0.5, 6.0)
        a = rng.standard_normal()
        phi = rng.uniform(0.0, 2.0 * np.pi)
        p += eps * a * np.cos(np.pi * f * x + phi)
    p = np.clip(p, 0.5, 1.5)
    return np.maximum(0.0, h * p)


def block_perturb(h, rng):
    N = len(h)
    K = int(rng.choice([4, 8, 16]))
    K = min(K, N)
    sigma = rng.uniform(0.05, 0.20)
    edges = np.linspace(0, N, K + 1).astype(int)
    p = np.ones(N)
    for b in range(K):
        lo, hi = edges[b], edges[b + 1]
        if hi <= lo:
            continue
        factor = float(np.exp(rng.normal(0.0, sigma)))
        p[lo:hi] *= factor
    return np.maximum(0.0, h * p)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82
    rng = np.random.default_rng(20240823)

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best_r = R_of(best)
        print("start R =", best_r, "N =", len(best))
    else:
        best = np.ones(64)
        best_r = R_of(best)

    # Initial strong polish including coordinate descent
    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        if time.process_time() < deadline:
            h, r = coord_sweep(h, deadline, rng=rng)
        if r > best_r:
            best, best_r = h, r
        print(f"initial polish R={best_r:.6f} N={len(best)}")

    it = 0
    while time.process_time() < deadline:
        it += 1
        # Mix of perturbations and N changes
        mode = it % 6
        if mode == 0:
            # Try a larger N to allow finer structure
            N_new = min(50000, len(best) + int(rng.integers(20, 200)))
            cand = resample(best, N_new)
            cand = np.maximum(0.0, cand * (1.0 + 0.01 * rng.standard_normal(len(cand))))
        elif mode == 1:
            cand = block_perturb(best, rng)
        elif mode == 2:
            # Slightly smaller N
            N_new = max(16, len(best) - int(rng.integers(10, 100)))
            cand = resample(best, N_new)
        elif mode == 3:
            cand = smooth_perturb(best, rng)
        elif mode == 4:
            # Double N (rare, expensive)
            N_new = min(50000, 2 * len(best))
            cand = resample(best, N_new)
        else:
            cand = smooth_perturb(best, rng, eps=rng.uniform(0.02, 0.15))

        h, r = polish_lbfgs(cand, deadline)
        if time.process_time() >= deadline:
            if r > best_r:
                best, best_r = h, r
            break
        if it % 3 == 0 and time.process_time() < deadline:
            h2, r2 = coord_sweep(h, deadline, rng=rng)
            if r2 > r:
                h, r = h2, r2

        if r > best_r:
            best, best_r = h, r
            print(f"hop {it} mode={mode}: accepted R={best_r:.6f} N={len(best)}")

    # Final polish at current N and nearby Ns
    for N_f in (len(best), max(64, len(best) - 10), len(best) + 10):
        if time.process_time() >= deadline:
            break
        seed = resample(best, N_f)
        h, r = polish_lbfgs(seed, deadline)
        if time.process_time() < deadline:
            h2, r2 = coord_sweep(h, deadline, rng=rng)
            if r2 > r:
                h, r = h2, r2
        if r > best_r:
            best, best_r = h, r
            print(f"final N={N_f} R={best_r:.6f}")

    if time.process_time() < deadline:
        h, r = polish_lbfgs(best, deadline)
        if r > best_r:
            best, best_r = h, r

    print("final R =", best_r, "N =", len(best))
    return np.asarray(best, dtype=float)

